  "type": "module",
  "main": "index.ts",
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest",
    "diff": "^8.0.2"
  },
  "devDependencies": {
    "@types/diff": "^7.0.2",
    "bun-types": "latest",
    "typescript": "^5.0.0"
  },
  "keywords": [
    "opencode",
